// Stable item IDs; semantic five-level anchors, plus an explicitly unscored unknown.
export const tr=(value,locale='en')=>typeof value==='string'?value:(value?.[locale]??value?.en??'');
const T=(en,zh,ms)=>({en,'zh-CN':zh,ms});
const skills=[
 ['analysis',T('Interpret a small table and check a conclusion','解读小型数据表并核查结论','Tafsir jadual kecil dan semak kesimpulan'),T('Analysis','分析能力','Analisis')],
 ['communication',T('Explain a recommendation to someone with different knowledge','向不同知识背景的人解释建议','Terangkan cadangan kepada orang berlatar pengetahuan berbeza'),T('Communication','沟通能力','Komunikasi')],
 ['planning',T('Plan a task with deadlines and dependencies','规划有期限和依赖关系的任务','Rancang tugas dengan tarikh akhir dan kebergantungan'),T('Planning','计划协调','Perancangan')],
 ['technical',T('Build or debug a small spreadsheet formula or script','编写或排查简单表格公式或脚本','Bina atau nyahpepijat formula hamparan atau skrip ringkas'),T('Technical practice','技术实践','Amalan teknikal')],
 ['aiCollaboration',T('Check an AI draft against original evidence','根据原始证据检查 AI 草稿','Semak draf AI dengan bukti asal'),T('AI collaboration','AI 协作','Kerjasama AI')]
];
const abilityLevels=[
 T('Not yet · I need a worked example and guidance throughout.','尚未掌握 · 需要完整示例与全程指导。','Belum mahir · Perlu contoh lengkap dan bimbingan sepanjang tugas.'),
 T('Starting · I can follow a demonstrated method on a simple example.','开始入门 · 能按照演示方法完成简单示例。','Baru bermula · Boleh ikut kaedah yang ditunjukkan pada contoh mudah.'),
 T('Working independently · I can complete a routine example and spot obvious errors.','能够独立完成 · 能完成常规示例，并发现明显错误。','Boleh berdikari · Mampu siapkan contoh rutin dan kesan ralat jelas.'),
 T('Confident · I can adapt the method to a new case and explain my checks.','比较熟练 · 能将方法用于新情境，并解释检查过程。','Agak mahir · Boleh sesuaikan kaedah untuk kes baharu dan terangkan semakan.'),
 T('Advanced · I can handle ambiguous cases, compare methods and review another person’s work.','熟练应用 · 能处理不明确的情况、比较方法并评审他人成果。','Mahir · Boleh tangani kes kabur, banding kaedah dan semak hasil orang lain.')
];
const interests=[['research',T('Investigating why something happens','探究事情背后的原因','Menyiasat mengapa sesuatu berlaku')],['people',T('Helping people coordinate and work together','帮助他人协调合作','Membantu orang menyelaras dan bekerjasama')],['creative',T('Creating new ideas and ways to present them','创造新点子及表达方式','Mencipta idea dan cara penyampaian baharu')]];
const interestLevels=[T('Avoid · I would usually choose another task.','尽量避免 · 通常会选择其他任务。','Elak · Biasanya memilih tugas lain.'),T('Low interest · I do this when necessary.','兴趣较低 · 必要时才做。','Minat rendah · Lakukan jika perlu.'),T('Open · I am willing to try it.','愿意尝试 · 可以探索这类任务。','Terbuka · Sanggup mencuba.'),T('Enjoy · I often choose this kind of activity.','比较喜欢 · 经常主动选择。','Suka · Kerap memilih aktiviti begini.'),T('Strong interest · I seek it out and want to explore it further.','非常喜欢 · 会主动寻找机会深入探索。','Sangat minat · Mencari peluang untuk menerokanya lagi.')];
export const questions=[...skills.map(([id,prompt,title])=>({id,prompt,title,kind:'ability',step:id==='aiCollaboration'?2:1,levels:abilityLevels})),...interests.map(([id,prompt])=>({id,prompt,title:prompt,kind:'interest',step:2,levels:interestLevels})),
 {id:'structure',kind:'preference',step:3,title:T('Structure preference','结构化偏好','Keutamaan struktur'),prompt:T('How much routine and clear procedure do you prefer?','你希望工作有多少固定流程？','Sejauh mana anda mengutamakan rutin dan prosedur jelas?'),levels:[T('Very little · prefer open exploration.','很少 · 喜欢开放探索。','Sangat sedikit · Suka penerokaan terbuka.'),T('Some · prefer flexible guidelines.','较少 · 灵活指引即可。','Sedikit · Panduan fleksibel.'),T('Balanced · mix of guidance and flexibility.','平衡 · 指引与灵活并存。','Seimbang · Panduan dan fleksibiliti.'),T('Mostly structured · prefer clear steps.','较多 · 喜欢明确步骤。','Agak berstruktur · Langkah jelas.'),T('Highly structured · prefer predictable procedures.','很多 · 喜欢可预期的流程。','Sangat berstruktur · Prosedur boleh dijangka.')]},
 {id:'autonomy',kind:'preference',step:3,title:T('Autonomy preference','自主性偏好','Keutamaan autonomi'),prompt:T('How much freedom do you want in choosing your methods?','你希望有多少选择工作方法的自主权？','Sejauh mana kebebasan memilih kaedah kerja yang anda inginkan?'),levels:[T('Close guidance · want frequent direction.','密切指导 · 希望经常获得指引。','Bimbingan rapat · Arahan kerap.'),T('Guided · want regular checkpoints.','定期指导 · 希望有固定检查点。','Berpandukan · Semakan berkala.'),T('Shared · decide methods with others.','共同决定 · 与他人商量方法。','Bersama · Tentukan kaedah dengan orang lain.'),T('Mostly independent · choose methods within agreed goals.','较为自主 · 在共同目标下自行选方法。','Kebanyakannya bebas · Pilih kaedah dalam matlamat dipersetujui.'),T('Highly independent · want to define and test my approach.','高度自主 · 希望自行定义并验证方案。','Sangat bebas · Tentukan dan uji pendekatan sendiri.')]}];
export const education=[['unknown',T('Not sure / prefer not to specify','不确定／暂不说明','Tidak pasti / belum mahu nyatakan')],['secondary',T('Secondary education or equivalent','中学或同等学历','Pendidikan menengah atau setara')],['diploma',T('Diploma / vocational qualification','文凭／职业资格','Diploma / kelayakan vokasional')],['degree',T('Degree or equivalent completed qualification','已完成学位或同等资格','Ijazah atau kelayakan setara yang telah selesai')]];
export const unknown=T('Not sure / not familiar · excluded from scoring, not treated as zero.','不确定／不了解 · 不计入评分，不当作零分。','Tidak pasti / tidak biasa · Dikecualikan daripada skor, bukan dianggap sifar.');
export function rating(value){return Number.isInteger(Number(value))&&Number(value)>=1&&Number(value)<=5?Number(value):null;}
export function validateRatings(profile,step){return Object.fromEntries(questions.filter(q=>q.step===step && ![1,2,3,4,5,'unknown'].includes(profile.assessment?.[q.id])).map(q=>['rating-'+q.id,'Please choose an answer.']));}
export const labels={T};
